const FlameParticle: React.FC<{ index: number; textWidth: number }> = ({
  index,
  textWidth,
}) => {
  const frame = useCurrentFrame();

  // Stable randoms based on index
  const seed = useMemo(() => index * 12345, [index]);
  const rScale = random(`scale-${seed}`);
  const rX = random(`x-${seed}`);
  const rSpeed = random(`speed-${seed}`);

  const lifeSpan = Math.floor(40 + rSpeed * 30);
  const birthFrame = Math.floor(random(`birth-${seed}`) * lifeSpan);
  const localFrame = (frame + birthFrame) % lifeSpan;
  const progress = localFrame / lifeSpan;

  // Animation math
  const yOffset = interpolate(progress, [0, 1], [40, -350 - rSpeed * 100]);
  const xOffset = (rX - 0.5) * (textWidth + 100);

  // Wobble effect
  const wobble = Math.sin(progress * Math.PI * 4) * 20 * rScale;

  const scale = interpolate(
    progress,
    [0, 0.2, 0.7, 1],
    [0, 1.2 * rScale + 0.8, 0.8 * rScale + 0.5, 0]
  );
  const opacity = interpolate(
    progress,
    [0, 0.1, 0.8, 1],
    [0, 0.8, 0.6, 0]
  );

  // Color shifting from yellow (bottom) to red (top)
  const r = 255;
  const g = Math.floor(interpolate(progress, [0, 0.5, 1], [220, 80, 0]));
  const b = Math.floor(interpolate(progress, [0, 0.2], [50, 0]));

  return (
    <div
      style={{
        position: "absolute",
        bottom: 0,
        left: "50%",
        width: 100,
        height: 100,
        backgroundColor: `rgb(${r}, ${g}, ${b})`,
        borderRadius: "50% 0 50% 50%",
        transform: `translate(-50%, ${yOffset}px) translateX(${
          xOffset + wobble
        }px) rotate(45deg) scale(${scale})`,
        opacity,
        filter: "blur(12px)",
        mixBlendMode: "screen",
        willChange: "transform, opacity",
        transition: "none",
      }}
    />
  );
};

const PersonDrop: React.FC<{
  index: number;
  startFrame: number;
  fps: number;
  canX: number;
  canY: number;
  fireY: number;
  emoji: string;
}> = ({ index, startFrame, fps, canX, canY, fireY, emoji }) => {
  const frame = useCurrentFrame();

  const spawnDelay = index * 3;
  const myStartFrame = startFrame + spawnDelay;
  const dropDuration = fps * 1.8; // 1.8 seconds to fall

  const progress = interpolate(
    frame,
    [myStartFrame, myStartFrame + dropDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  if (frame < myStartFrame || progress >= 1) return null;

  // Quadratic fall (gravity)
  const y = interpolate(progress, [0, 1], [canY, fireY], {
    easing: Easing.in(Easing.quad),
  });

  // Spread outwards then inwards
  const spreadMultiplier = random(`spread-${index}`) * 200 - 100;
  const xArc = Math.sin(progress * Math.PI) * spreadMultiplier;
  const x = canX + xArc + (random(`x-${index}`) * 40 - 20);

  const rotation = interpolate(
    progress,
    [0, 1],
    [0, (random(`rot-${index}`) - 0.5) * 1080]
  );
  
  const scale = interpolate(progress, [0, 0.1, 0.9, 1], [0, 1, 1, 0.5]);
  const opacity = interpolate(progress, [0, 0.1, 0.9, 1], [0, 1, 1, 0]);

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        transform: `translate(-50%, -50%) rotate(${rotation}deg) scale(${scale})`,
        opacity,
        fontSize: 70,
        filter: "drop-shadow(0px 5px 5px rgba(0,0,0,0.5))",
        transition: "none",
        zIndex: 10,
      }}
    >
      {emoji}
    </div>
  );
};


const RoasFire: React.FC<RoasFireProps> = ({
  backgroundColor = "#0d0d0d",
  transparentBackground = false,
  durationInSeconds = 6,
  targetRoas = 8.25,
  roasColor = "#ffffff",
  wateringCanColor = "#4A90E2",
  peopleEmoji = "👤",
  fireIntensity = 60,
}) => {
  useFontLoader(["Anton"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Layout Constants ---
  const centerX = width * 0.5;
  const canY = height * 0.25;
  const fireY = height * 0.75;
  
  // --- Animation Timings ---
  const canTiltStartFrame = fps * 0.5;
  const pourStartFrame = canTiltStartFrame + 10;
  const roasIncrementStartFrame = pourStartFrame + fps; // Start counting when people hit
  const roasIncrementEndFrame = Math.max(roasIncrementStartFrame + 1, durationInFrames - fps * 0.5); // Ensure strictly monotonically increasing

  // --- Calculations ---
  
  // Can Tilt (-50 degrees to tip it over)
  const canRotation = interpolate(
    spring({
      frame: frame - canTiltStartFrame,
      fps,
      config: { damping: 14, stiffness: 80 },
    }),
    [0, 1],
    [0, -55]
  );

  // Can Spout position approximation (shifts left and down as it rotates)
  const spoutWorldX = centerX - 120 + interpolate(canRotation, [-55, 0], [-40, 0]);
  const spoutWorldY = canY + 40 + interpolate(canRotation, [-55, 0], [60, 0]);

  // ROAS Counter Logic
  const roasProgress = interpolate(
    frame,
    [roasIncrementStartFrame, roasIncrementEndFrame],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) }
  );
  
  const currentRoas = interpolate(
    roasProgress,
    [0, 1],
    [0, targetRoas]
  );

  const displayRoas = currentRoas.toFixed(2);

  // Pulse effect on the ROAS text based on fire
  const pulseScale = 1 + Math.sin(frame * 0.2) * 0.02;

  // Number of people to drop based on remaining duration
  const totalPeopleFrames = durationInFrames - pourStartFrame - fps;
  const totalPeople = Math.max(0, Math.floor(totalPeopleFrames / 3));
  const dropArray = useMemo(() => Array.from({ length: totalPeople }), [totalPeople]);
  
  // Fire Particles arrays (split behind and in front of text)
  const backFlames = useMemo(() => Array.from({ length: Math.floor(fireIntensity * 0.6) }), [fireIntensity]);
  const frontFlames = useMemo(() => Array.from({ length: Math.floor(fireIntensity * 0.4) }), [fireIntensity]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none", overflow: "hidden" }}>
      
      {/* BACKGROUND GLOW */}
      <div
        style={{
          position: "absolute",
          left: centerX,
          top: fireY,
          width: 600,
          height: 600,
          transform: "translate(-50%, -50%)",
          background: "radial-gradient(circle, rgba(255,100,0,0.15) 0%, rgba(0,0,0,0) 70%)",
          opacity: interpolate(frame, [0, 30], [0, 1], { extrapolateRight: "clamp" }),
        }}
      />

      {/* FALLING PEOPLE */}
      {dropArray.map((_, i) => (
        <PersonDrop
          key={`drop-${i}`}
          index={i}
          startFrame={pourStartFrame}
          fps={fps}
          canX={spoutWorldX}
          canY={spoutWorldY}
          fireY={fireY}
          emoji={peopleEmoji}
        />
      ))}

      {/* WATERING CAN */}
      <div
        style={{
          position: "absolute",
          left: centerX,
          top: canY,
          width: 300,
          height: 300,
          transform: `translate(-50%, -50%) rotate(${canRotation}deg)`,
          transformOrigin: "65% 50%", // Rotate roughly around the handle/center mass
          zIndex: 20,
        }}
      >
        <WateringCanSvg color={wateringCanColor} />
      </div>

      {/* FIRE CONTAINER (Bottom section) */}
      <div
        style={{
          position: "absolute",
          left: centerX,
          top: fireY,
          width: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: "translate(-50%, -50%)",
        }}
      >
        <div style={{ position: "relative", width: 450, height: 200 }}>
          
          {/* BACK FLAMES */}
          {backFlames.map((_, i) => (
            <FlameParticle key={`back-${i}`} index={i} textWidth={350} />
          ))}

          {/* ROAS TEXT */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              fontFamily: "Anton",
              fontSize: 180,
              fontWeight: 800,
              color: roasColor,
              letterSpacing: "0.02em",
              transform: `scale(${pulseScale})`,
              textShadow: "0px 10px 30px rgba(0,0,0,0.8), 0px 0px 40px rgba(255,100,0,0.6)",
              zIndex: 5,
              whiteSpace: "nowrap",
            }}
          >
            {displayRoas}
            <span style={{ fontSize: 100, marginLeft: 10, opacity: 0.9 }}>x</span>
          </div>

          {/* FRONT FLAMES */}
          {frontFlames.map((_, i) => (
            <FlameParticle key={`front-${i}`} index={i + 1000} textWidth={400} />
          ))}

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default RoasFire;